-- Campus Social database setup. Generated by scripts/make-setup-sql.sh; do not edit.
--
-- For a NEW, empty Supabase project: open SQL Editor, paste this whole file,
-- press Run. Everything runs in one transaction, so if anything fails nothing
-- is changed. Projects that already ran it only need the newer files in
-- supabase/migrations/ (or 'supabase db push').

begin;

-- ===== 20261022000000_init.sql =====

-- CUHK Campus: initial schema
-- Societies, follows, events with capacity + waitlist, QR check-in,
-- promotional banners, campus calendar dates, reports, account deletion.

-- ---------------------------------------------------------------------------
-- Types
-- ---------------------------------------------------------------------------
create type public.society_role as enum ('owner', 'admin', 'editor');
create type public.event_status as enum ('draft', 'published', 'cancelled');
create type public.registration_status as enum ('confirmed', 'waitlisted', 'cancelled');
create type public.review_status as enum ('pending', 'approved', 'rejected');

-- ---------------------------------------------------------------------------
-- Profiles (one per auth user, CUHK emails only)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text not null,
  display_name text not null default '',
  college text,
  major text,
  year_of_study int check (year_of_study between 1 and 8),
  avatar_url text,
  is_platform_admin boolean not null default false,
  created_at timestamptz not null default now()
);

-- Extra addresses allowed to sign up (e.g. the App Store review account).
create table public.allowed_emails (
  email text primary key,
  note text
);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (
    lower(new.email) ~ '@([a-z0-9-]+\.)*cuhk\.edu\.hk$'
    or exists (select 1 from public.allowed_emails a where a.email = lower(new.email))
  ) then
    raise exception 'Please sign in with your CUHK email address';
  end if;

  insert into public.profiles (id, email, display_name)
  values (new.id, lower(new.email), split_part(new.email, '@', 1));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create or replace function public.is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select p.is_platform_admin from public.profiles p where p.id = auth.uid()), false);
$$;

-- ---------------------------------------------------------------------------
-- Societies
-- ---------------------------------------------------------------------------
create table public.societies (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  short_name text,
  description text not null default '',
  category text not null default 'Other',
  college text,
  logo_url text,
  cover_url text,
  instagram text,
  website text,
  contact_email text,
  status public.review_status not null default 'pending',
  verified boolean not null default false,
  follower_count int not null default 0,
  created_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now()
);

create table public.society_members (
  society_id uuid not null references public.societies on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  role public.society_role not null default 'editor',
  created_at timestamptz not null default now(),
  primary key (society_id, user_id)
);

create or replace function public.is_society_member(sid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.society_members m
    where m.society_id = sid and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_society_admin(sid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.society_members m
    where m.society_id = sid and m.user_id = auth.uid() and m.role in ('owner', 'admin')
  );
$$;

-- Whoever registers a society becomes its owner.
create or replace function public.handle_new_society()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.created_by is not null then
    insert into public.society_members (society_id, user_id, role)
    values (new.id, new.created_by, 'owner')
    on conflict do nothing;
  end if;
  return new;
end;
$$;

create trigger on_society_created
  after insert on public.societies
  for each row execute function public.handle_new_society();

-- Students register a society through this RPC; it starts as "pending" until
-- a platform admin approves it, so nobody can impersonate an official society.
create or replace function public.create_society(
  p_name text,
  p_short_name text,
  p_description text,
  p_category text,
  p_college text,
  p_instagram text,
  p_contact_email text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in to register a society';
  end if;
  insert into public.societies (name, short_name, description, category, college, instagram, contact_email, created_by)
  values (p_name, nullif(p_short_name, ''), coalesce(p_description, ''), coalesce(p_category, 'Other'),
          nullif(p_college, ''), nullif(p_instagram, ''), nullif(p_contact_email, ''), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

create table public.follows (
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  society_id uuid not null references public.societies on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, society_id)
);

create index follows_society_idx on public.follows (society_id);

create or replace function public.sync_follower_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    update public.societies set follower_count = follower_count + 1 where id = new.society_id;
  else
    update public.societies set follower_count = greatest(follower_count - 1, 0) where id = old.society_id;
  end if;
  return null;
end;
$$;

create trigger on_follow_change
  after insert or delete on public.follows
  for each row execute function public.sync_follower_count();

-- ---------------------------------------------------------------------------
-- Events
-- ---------------------------------------------------------------------------
create table public.events (
  id uuid primary key default gen_random_uuid(),
  society_id uuid not null references public.societies on delete cascade,
  title text not null check (char_length(title) between 3 and 140),
  description text not null default '',
  category text not null default 'Social',
  location text not null default '',
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  cover_url text,
  status public.event_status not null default 'draft',
  registration_required boolean not null default true,
  capacity int check (capacity is null or capacity > 0),
  waitlist_enabled boolean not null default true,
  registration_opens_at timestamptz,
  registration_closes_at timestamptz,
  price_text text,
  confirmed_count int not null default 0,
  waitlist_count int not null default 0,
  created_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at >= starts_at)
);

create index events_starts_idx on public.events (starts_at);
create index events_society_idx on public.events (society_id, starts_at);

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger events_touch before update on public.events
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Registrations (tickets). Written only through the RPCs below so capacity
-- and waitlist stay consistent under concurrent sign-ups.
-- ---------------------------------------------------------------------------
create table public.registrations (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  status public.registration_status not null,
  ticket_code text not null unique default replace(gen_random_uuid()::text, '-', ''),
  checked_in_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, user_id)
);

create index registrations_waitlist_idx on public.registrations (event_id, status, created_at);
create index registrations_user_idx on public.registrations (user_id);

-- Promote waitlisted people while there is room. Caller must hold the event row lock.
create or replace function public._fill_from_waitlist(p_event_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.events;
  v_next uuid;
begin
  select * into v_event from public.events where id = p_event_id;
  while v_event.capacity is null or v_event.confirmed_count < v_event.capacity loop
    select r.id into v_next
    from public.registrations r
    where r.event_id = p_event_id and r.status = 'waitlisted'
    order by r.created_at
    limit 1;
    exit when v_next is null;

    update public.registrations set status = 'confirmed', updated_at = now() where id = v_next;
    update public.events
      set confirmed_count = confirmed_count + 1, waitlist_count = greatest(waitlist_count - 1, 0)
      where id = p_event_id
      returning * into v_event;
    v_next := null;
  end loop;
end;
$$;

create or replace function public.on_event_capacity_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public._fill_from_waitlist(new.id);
  return null;
end;
$$;

create trigger event_capacity_changed
  after update of capacity on public.events
  for each row
  when (old.capacity is distinct from new.capacity)
  execute function public.on_event_capacity_change();

create or replace function public.register_for_event(p_event_id uuid)
returns public.registrations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_event public.events;
  v_reg public.registrations;
  v_status public.registration_status;
begin
  if v_uid is null then
    raise exception 'Sign in to register for events';
  end if;

  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null or v_event.status <> 'published' then
    raise exception 'This event is not open for registration';
  end if;
  if not v_event.registration_required then
    raise exception 'No sign-up needed for this event, just turn up!';
  end if;
  if v_event.registration_opens_at is not null and now() < v_event.registration_opens_at then
    raise exception 'Registration has not opened yet';
  end if;
  if now() > coalesce(v_event.registration_closes_at, v_event.starts_at) then
    raise exception 'Registration has closed';
  end if;

  select * into v_reg from public.registrations where event_id = p_event_id and user_id = v_uid;
  if v_reg.id is not null and v_reg.status <> 'cancelled' then
    return v_reg;
  end if;

  if v_event.capacity is null or v_event.confirmed_count < v_event.capacity then
    v_status := 'confirmed';
  elsif v_event.waitlist_enabled then
    v_status := 'waitlisted';
  else
    raise exception 'Sorry, this event is full';
  end if;

  if v_reg.id is not null then
    -- Re-registering after cancelling: goes to the back of the queue.
    update public.registrations
      set status = v_status, checked_in_at = null, created_at = now(), updated_at = now()
      where id = v_reg.id
      returning * into v_reg;
  else
    insert into public.registrations (event_id, user_id, status)
      values (p_event_id, v_uid, v_status)
      returning * into v_reg;
  end if;

  update public.events
    set confirmed_count = confirmed_count + (v_status = 'confirmed')::int,
        waitlist_count = waitlist_count + (v_status = 'waitlisted')::int
    where id = p_event_id;

  return v_reg;
end;
$$;

create or replace function public.cancel_registration(p_event_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_reg public.registrations;
begin
  perform 1 from public.events where id = p_event_id for update;

  select * into v_reg from public.registrations
    where event_id = p_event_id and user_id = v_uid;
  if v_reg.id is null or v_reg.status = 'cancelled' then
    return;
  end if;

  update public.registrations set status = 'cancelled', updated_at = now() where id = v_reg.id;

  if v_reg.status = 'confirmed' then
    update public.events set confirmed_count = greatest(confirmed_count - 1, 0) where id = p_event_id;
    perform public._fill_from_waitlist(p_event_id);
  else
    update public.events set waitlist_count = greatest(waitlist_count - 1, 0) where id = p_event_id;
  end if;
end;
$$;

create or replace function public.waitlist_position(p_event_id uuid)
returns int
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::int
  from public.registrations r, public.registrations mine
  where mine.event_id = p_event_id
    and mine.user_id = auth.uid()
    and mine.status = 'waitlisted'
    and r.event_id = p_event_id
    and r.status = 'waitlisted'
    and r.created_at <= mine.created_at;
$$;

create or replace function public.check_in(p_event_id uuid, p_ticket_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_society uuid;
  v_reg public.registrations;
  v_name text;
begin
  select society_id into v_society from public.events where id = p_event_id;
  if v_society is null or not public.is_society_member(v_society) then
    raise exception 'Only society committee members can check people in';
  end if;

  select * into v_reg from public.registrations where ticket_code = p_ticket_code;
  if v_reg.id is null then
    return jsonb_build_object('ok', false, 'message', 'Ticket not found');
  end if;

  select coalesce(nullif(p.display_name, ''), p.email) into v_name
    from public.profiles p where p.id = v_reg.user_id;

  if v_reg.event_id <> p_event_id then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'This ticket is for a different event');
  end if;
  if v_reg.status <> 'confirmed' then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'Ticket is ' || v_reg.status::text || ', not confirmed');
  end if;
  if v_reg.checked_in_at is not null then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'Already checked in at ' || to_char(v_reg.checked_in_at at time zone 'Asia/Hong_Kong', 'HH24:MI'));
  end if;

  update public.registrations set checked_in_at = now(), updated_at = now() where id = v_reg.id;
  return jsonb_build_object('ok', true, 'name', v_name, 'message', 'Checked in');
end;
$$;

create or replace function public.list_attendees(p_event_id uuid)
returns table (
  registration_id uuid,
  display_name text,
  email text,
  college text,
  status public.registration_status,
  checked_in_at timestamptz,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_society_member((select e.society_id from public.events e where e.id = p_event_id)) then
    raise exception 'Only society committee members can see attendees';
  end if;
  return query
    select r.id, p.display_name, p.email, p.college, r.status, r.checked_in_at, r.created_at
    from public.registrations r
    join public.profiles p on p.id = r.user_id
    where r.event_id = p_event_id and r.status <> 'cancelled'
    order by r.status, r.created_at;
end;
$$;

-- ---------------------------------------------------------------------------
-- Promotional banners (reviewed before going live)
-- ---------------------------------------------------------------------------
create table public.banners (
  id uuid primary key default gen_random_uuid(),
  society_id uuid not null references public.societies on delete cascade,
  event_id uuid references public.events on delete cascade,
  title text not null check (char_length(title) between 3 and 80),
  subtitle text,
  image_url text,
  starts_at timestamptz not null default now(),
  ends_at timestamptz not null,
  priority int not null default 0,
  status public.review_status not null default 'pending',
  created_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at)
);

create or replace function public.review_society(p_id uuid, p_status public.review_status, p_verified boolean default false)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'Admins only';
  end if;
  update public.societies set status = p_status, verified = p_verified where id = p_id;
end;
$$;

create or replace function public.review_banner(p_id uuid, p_status public.review_status, p_priority int default 0)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'Admins only';
  end if;
  update public.banners set status = p_status, priority = p_priority where id = p_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- University / college calendar
-- ---------------------------------------------------------------------------
create table public.campus_dates (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  kind text not null default 'university'
    check (kind in ('university', 'college', 'holiday', 'term', 'exam', 'deadline')),
  college text,
  starts_on date not null,
  ends_on date not null,
  url text,
  created_at timestamptz not null default now(),
  check (ends_on >= starts_on)
);

create index campus_dates_starts_idx on public.campus_dates (starts_on);

-- ---------------------------------------------------------------------------
-- Reports (App Store guideline 1.2: user-generated content must be reportable)
-- ---------------------------------------------------------------------------
create table public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter uuid default auth.uid() references auth.users on delete set null,
  target_type text not null check (target_type in ('event', 'society', 'banner')),
  target_id uuid not null,
  reason text not null check (char_length(reason) between 3 and 1000),
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- In-app account deletion (App Store guideline 5.1.1(v))
-- ---------------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_event uuid;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  -- Free up seats first so waitlists move and counts stay right.
  for v_event in
    select event_id from public.registrations where user_id = v_uid and status <> 'cancelled'
  loop
    perform public.cancel_registration(v_event);
  end loop;
  delete from auth.users where id = v_uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.allowed_emails enable row level security;
alter table public.societies enable row level security;
alter table public.society_members enable row level security;
alter table public.follows enable row level security;
alter table public.events enable row level security;
alter table public.registrations enable row level security;
alter table public.banners enable row level security;
alter table public.campus_dates enable row level security;
alter table public.reports enable row level security;

-- Column-level privileges: users can never write counters, review status or admin flags.
revoke insert, update, delete on all tables in schema public from anon, authenticated;

grant update (display_name, college, major, year_of_study, avatar_url) on public.profiles to authenticated;
grant update (name, short_name, description, category, college, logo_url, cover_url, instagram, website, contact_email)
  on public.societies to authenticated;
grant insert, delete on public.society_members to authenticated;
grant update (role) on public.society_members to authenticated;
grant insert (society_id), delete on public.follows to authenticated;
grant insert (society_id, title, description, category, location, starts_at, ends_at, cover_url, status,
  registration_required, capacity, waitlist_enabled, registration_opens_at, registration_closes_at, price_text)
  on public.events to authenticated;
grant update (title, description, category, location, starts_at, ends_at, cover_url, status,
  registration_required, capacity, waitlist_enabled, registration_opens_at, registration_closes_at, price_text)
  on public.events to authenticated;
grant delete on public.events to authenticated;
grant insert (society_id, event_id, title, subtitle, image_url, starts_at, ends_at), delete
  on public.banners to authenticated;
grant insert, update, delete on public.campus_dates to authenticated;
grant insert (target_type, target_id, reason) on public.reports to authenticated;

revoke execute on function public._fill_from_waitlist(uuid) from public, anon, authenticated;

-- profiles
create policy "read own profile" on public.profiles
  for select using (id = auth.uid() or public.is_platform_admin());
create policy "update own profile" on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());

-- societies
create policy "read approved or own societies" on public.societies
  for select using (status = 'approved' or public.is_society_member(id) or public.is_platform_admin());
create policy "society admins edit" on public.societies
  for update using (public.is_society_admin(id)) with check (public.is_society_admin(id));

-- society_members
create policy "members see their committee" on public.society_members
  for select using (user_id = auth.uid() or public.is_society_member(society_id) or public.is_platform_admin());
create policy "admins add members" on public.society_members
  for insert with check (public.is_society_admin(society_id) and role <> 'owner');
create policy "admins change roles" on public.society_members
  for update using (public.is_society_admin(society_id) and role <> 'owner')
  with check (role <> 'owner');
create policy "admins remove members or leave" on public.society_members
  for delete using ((public.is_society_admin(society_id) and role <> 'owner') or (user_id = auth.uid() and role <> 'owner'));

-- follows
create policy "see own follows" on public.follows
  for select using (user_id = auth.uid());
create policy "follow" on public.follows
  for insert to authenticated with check (user_id = auth.uid());
create policy "unfollow" on public.follows
  for delete using (user_id = auth.uid());

-- events
create policy "read public events" on public.events
  for select using (
    (status in ('published', 'cancelled')
      and exists (select 1 from public.societies s where s.id = society_id and s.status = 'approved'))
    or public.is_society_member(society_id)
  );
create policy "committee creates events" on public.events
  for insert to authenticated with check (public.is_society_member(society_id));
create policy "committee edits events" on public.events
  for update using (public.is_society_member(society_id)) with check (public.is_society_member(society_id));
create policy "admins delete events" on public.events
  for delete using (public.is_society_admin(society_id));

-- registrations: read only; writes go through RPCs
create policy "see own tickets" on public.registrations
  for select using (user_id = auth.uid());

-- banners
create policy "read live banners" on public.banners
  for select using (
    (status = 'approved' and now() between starts_at and ends_at)
    or public.is_society_member(society_id)
    or public.is_platform_admin()
  );
create policy "committee requests banners" on public.banners
  for insert to authenticated with check (
    public.is_society_member(society_id)
    and (event_id is null or exists (select 1 from public.events e where e.id = event_id and e.society_id = banners.society_id))
  );
create policy "committee removes banners" on public.banners
  for delete using (public.is_society_member(society_id));

-- campus dates
create policy "anyone reads campus dates" on public.campus_dates for select using (true);
create policy "admins write campus dates" on public.campus_dates
  for all to authenticated using (public.is_platform_admin()) with check (public.is_platform_admin());

-- reports
create policy "file reports" on public.reports
  for insert to authenticated with check (reporter = auth.uid());
create policy "admins read reports" on public.reports
  for select using (public.is_platform_admin());

-- ---------------------------------------------------------------------------
-- Storage: public "media" bucket, users upload into a folder named after their id
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public)
values ('media', 'media', true)
on conflict (id) do nothing;

create policy "upload own media" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "manage own media" on storage.objects
  for delete to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);

-- ===== 20261022010000_short_ticket_codes.sql =====

-- Allow manual check-in with the short code shown under each QR ticket.

create or replace function public.check_in(p_event_id uuid, p_ticket_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_society uuid;
  v_reg public.registrations;
  v_name text;
  v_matches int;
begin
  select society_id into v_society from public.events where id = p_event_id;
  if v_society is null or not public.is_society_member(v_society) then
    raise exception 'Only society committee members can check people in';
  end if;

  select * into v_reg from public.registrations where ticket_code = lower(trim(p_ticket_code));

  -- Door staff can also type the 8-character code printed under the QR.
  if v_reg.id is null and char_length(trim(p_ticket_code)) = 8 then
    select count(*) into v_matches from public.registrations
      where event_id = p_event_id and ticket_code like lower(trim(p_ticket_code)) || '%';
    if v_matches > 1 then
      return jsonb_build_object('ok', false, 'message', 'Several tickets match that code, please scan the QR instead');
    end if;
    select * into v_reg from public.registrations
      where event_id = p_event_id and ticket_code like lower(trim(p_ticket_code)) || '%';
  end if;

  if v_reg.id is null then
    return jsonb_build_object('ok', false, 'message', 'Ticket not found');
  end if;

  select coalesce(nullif(p.display_name, ''), p.email) into v_name
    from public.profiles p where p.id = v_reg.user_id;

  if v_reg.event_id <> p_event_id then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'This ticket is for a different event');
  end if;
  if v_reg.status <> 'confirmed' then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'Ticket is ' || v_reg.status::text || ', not confirmed');
  end if;
  if v_reg.checked_in_at is not null then
    return jsonb_build_object('ok', false, 'name', v_name, 'message', 'Already checked in at ' || to_char(v_reg.checked_in_at at time zone 'Asia/Hong_Kong', 'HH24:MI'));
  end if;

  update public.registrations set checked_in_at = now(), updated_at = now() where id = v_reg.id;
  return jsonb_build_object('ok', true, 'name', v_name, 'message', 'Checked in');
end;
$$;

-- ===== 20261023000000_v02_notifications_committee_moderation.sql =====

-- v0.2: notifications, committee management, sign-up questions, manual
-- check-in, moderation of reports, push token storage.

-- ---------------------------------------------------------------------------
-- Notifications inbox (also the source for push delivery, see
-- supabase/functions/send-push)
-- ---------------------------------------------------------------------------
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  kind text not null check (kind in ('waitlist_promoted', 'event_cancelled', 'event_updated', 'new_event', 'society_approved', 'committee_added')),
  title text not null,
  body text not null default '',
  event_id uuid references public.events on delete cascade,
  society_id uuid references public.societies on delete cascade,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index notifications_user_idx on public.notifications (user_id, created_at desc);

alter table public.notifications enable row level security;
create policy "read own notifications" on public.notifications
  for select using (user_id = auth.uid());
create policy "mark own notifications read" on public.notifications
  for update using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "clear own notifications" on public.notifications
  for delete using (user_id = auth.uid());
-- Rows are written only by triggers and security definer functions.
revoke insert, update, delete on public.notifications from anon, authenticated;
grant update (read_at), delete on public.notifications to authenticated;

create or replace function public.mark_all_notifications_read()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.notifications set read_at = now() where user_id = auth.uid() and read_at is null;
$$;

-- Expo push tokens, one row per device.
create table public.push_tokens (
  token text primary key,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  platform text not null check (platform in ('ios', 'android', 'web')),
  updated_at timestamptz not null default now()
);

alter table public.push_tokens enable row level security;
create policy "manage own push tokens" on public.push_tokens
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());
-- Written through register_push_token; the app only deletes its token on sign-out.
revoke insert, update, delete on public.push_tokens from anon, authenticated;
grant delete on public.push_tokens to authenticated;

create or replace function public.register_push_token(p_token text, p_platform text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  -- A device that changes hands moves its token to the new account.
  insert into public.push_tokens (token, user_id, platform)
  values (p_token, auth.uid(), p_platform)
  on conflict (token) do update set user_id = auth.uid(), platform = excluded.platform, updated_at = now();
end;
$$;

-- Waitlist promotions: tell the person they got a spot.
create or replace function public.notify_registration_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_title text;
begin
  if old.status = 'waitlisted' and new.status = 'confirmed' then
    select title into v_title from public.events where id = new.event_id;
    insert into public.notifications (user_id, kind, title, body, event_id)
    values (new.user_id, 'waitlist_promoted', 'You got a spot!', 'A place opened up for ' || v_title || '. Your QR ticket is ready.', new.event_id);
  end if;
  return null;
end;
$$;

create trigger registration_status_changed
  after update of status on public.registrations
  for each row execute function public.notify_registration_change();

-- Event cancelled / moved, and new events for followers. The person making
-- the change is never notified about it.
create or replace function public.notify_event_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_society text;
begin
  select coalesce(short_name, name) into v_society from public.societies where id = new.society_id;

  if tg_op = 'UPDATE' and old.status = 'published' and new.status = 'cancelled' then
    insert into public.notifications (user_id, kind, title, body, event_id, society_id)
    select r.user_id, 'event_cancelled', 'Event cancelled', new.title || ' by ' || v_society || ' has been cancelled.', new.id, new.society_id
    from public.registrations r
    where r.event_id = new.id and r.status <> 'cancelled' and r.user_id is distinct from auth.uid();

  elsif tg_op = 'UPDATE' and old.status = 'published' and new.status = 'published'
    and (old.starts_at is distinct from new.starts_at or old.location is distinct from new.location) then
    insert into public.notifications (user_id, kind, title, body, event_id, society_id)
    select r.user_id, 'event_updated', 'Event details changed',
      new.title || ' has a new ' ||
        case when old.starts_at is distinct from new.starts_at and old.location is distinct from new.location then 'time and place'
             when old.starts_at is distinct from new.starts_at then 'time' else 'place' end || '. Check the details.',
      new.id, new.society_id
    from public.registrations r
    where r.event_id = new.id and r.status <> 'cancelled' and r.user_id is distinct from auth.uid();

  elsif new.status = 'published' and (tg_op = 'INSERT' or old.status = 'draft') and new.starts_at > now() then
    insert into public.notifications (user_id, kind, title, body, event_id, society_id)
    select f.user_id, 'new_event', 'New from ' || v_society, new.title, new.id, new.society_id
    from public.follows f
    where f.society_id = new.society_id and f.user_id is distinct from auth.uid();
  end if;
  return null;
end;
$$;

create trigger event_changed_notify
  after insert or update of status, starts_at, location on public.events
  for each row execute function public.notify_event_change();

-- ---------------------------------------------------------------------------
-- Sign-up question (Eventbrite-style "anything we should know?")
-- ---------------------------------------------------------------------------
alter table public.events add column signup_question text check (char_length(signup_question) <= 200);
alter table public.registrations add column answer text check (char_length(answer) <= 500);
grant insert (signup_question), update (signup_question) on public.events to authenticated;

drop function public.register_for_event(uuid);

create or replace function public.register_for_event(p_event_id uuid, p_answer text default null)
returns public.registrations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_event public.events;
  v_reg public.registrations;
  v_status public.registration_status;
  v_answer text := nullif(trim(p_answer), '');
begin
  if v_uid is null then
    raise exception 'Sign in to register for events';
  end if;

  select * into v_event from public.events where id = p_event_id for update;
  if v_event.id is null or v_event.status <> 'published' or v_event.removed_at is not null then
    raise exception 'This event is not open for registration';
  end if;
  if not v_event.registration_required then
    raise exception 'No sign-up needed for this event, just turn up!';
  end if;
  if v_event.registration_opens_at is not null and now() < v_event.registration_opens_at then
    raise exception 'Registration has not opened yet';
  end if;
  if now() > coalesce(v_event.registration_closes_at, v_event.starts_at) then
    raise exception 'Registration has closed';
  end if;

  select * into v_reg from public.registrations where event_id = p_event_id and user_id = v_uid;
  if v_reg.id is not null and v_reg.status <> 'cancelled' then
    return v_reg;
  end if;

  if v_event.capacity is null or v_event.confirmed_count < v_event.capacity then
    v_status := 'confirmed';
  elsif v_event.waitlist_enabled then
    v_status := 'waitlisted';
  else
    raise exception 'Sorry, this event is full';
  end if;

  if v_reg.id is not null then
    -- Re-registering after cancelling: goes to the back of the queue.
    update public.registrations
      set status = v_status, answer = v_answer, checked_in_at = null, created_at = now(), updated_at = now()
      where id = v_reg.id
      returning * into v_reg;
  else
    insert into public.registrations (event_id, user_id, status, answer)
      values (p_event_id, v_uid, v_status, v_answer)
      returning * into v_reg;
  end if;

  update public.events
    set confirmed_count = confirmed_count + (v_status = 'confirmed')::int,
        waitlist_count = waitlist_count + (v_status = 'waitlisted')::int
    where id = p_event_id;

  return v_reg;
end;
$$;

drop function public.list_attendees(uuid);

create or replace function public.list_attendees(p_event_id uuid)
returns table (
  registration_id uuid,
  display_name text,
  email text,
  college text,
  status public.registration_status,
  answer text,
  checked_in_at timestamptz,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_society_member((select e.society_id from public.events e where e.id = p_event_id)) then
    raise exception 'Only society committee members can see attendees';
  end if;
  return query
    select r.id, p.display_name, p.email, p.college, r.status, r.answer, r.checked_in_at, r.created_at
    from public.registrations r
    join public.profiles p on p.id = r.user_id
    where r.event_id = p_event_id and r.status <> 'cancelled'
    order by r.status, r.created_at;
end;
$$;

-- Tap an attendee to check them in (or undo) when they can't show a QR.
create or replace function public.set_checked_in(p_registration_id uuid, p_checked boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reg public.registrations;
  v_society uuid;
begin
  select * into v_reg from public.registrations where id = p_registration_id;
  select society_id into v_society from public.events where id = v_reg.event_id;
  if v_society is null or not public.is_society_member(v_society) then
    raise exception 'Only society committee members can check people in';
  end if;
  if p_checked and v_reg.status <> 'confirmed' then
    raise exception 'Only confirmed attendees can be checked in';
  end if;
  update public.registrations
    set checked_in_at = case when p_checked then coalesce(checked_in_at, now()) else null end, updated_at = now()
    where id = p_registration_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Committee members
-- ---------------------------------------------------------------------------
create or replace function public.list_society_members(p_society_id uuid)
returns table (user_id uuid, display_name text, email text, role public.society_role, created_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_society_member(p_society_id) then
    raise exception 'Only committee members can see the committee';
  end if;
  return query
    select m.user_id, p.display_name, p.email, m.role, m.created_at
    from public.society_members m
    join public.profiles p on p.id = m.user_id
    where m.society_id = p_society_id
    order by m.role, m.created_at;
end;
$$;

create or replace function public.add_society_member(p_society_id uuid, p_email text, p_role public.society_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
  v_name text;
begin
  if not public.is_society_admin(p_society_id) then
    raise exception 'Only society admins can add committee members';
  end if;
  if p_role = 'owner' then
    raise exception 'Use transfer ownership instead';
  end if;
  select id into v_user from public.profiles where email = lower(trim(p_email));
  if v_user is null then
    raise exception 'No account for that email yet. Ask them to sign in to the app once, then try again.';
  end if;
  insert into public.society_members (society_id, user_id, role)
  values (p_society_id, v_user, p_role)
  on conflict (society_id, user_id) do update set role = excluded.role
  where public.society_members.role <> 'owner';

  select coalesce(short_name, name) into v_name from public.societies where id = p_society_id;
  insert into public.notifications (user_id, kind, title, body, society_id)
  values (v_user, 'committee_added', 'You joined a committee', 'You can now manage events for ' || v_name || '.', p_society_id);
end;
$$;

create or replace function public.transfer_society_ownership(p_society_id uuid, p_new_owner uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.society_members
    where society_id = p_society_id and user_id = auth.uid() and role = 'owner'
  ) then
    raise exception 'Only the owner can transfer ownership';
  end if;
  if not exists (select 1 from public.society_members where society_id = p_society_id and user_id = p_new_owner) then
    raise exception 'The new owner must already be on the committee';
  end if;
  update public.society_members set role = 'admin' where society_id = p_society_id and user_id = auth.uid();
  update public.society_members set role = 'owner' where society_id = p_society_id and user_id = p_new_owner;
end;
$$;

-- Society approval also notifies the committee.
create or replace function public.review_society(p_id uuid, p_status public.review_status, p_verified boolean default false)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old public.review_status;
  v_name text;
begin
  if not public.is_platform_admin() then
    raise exception 'Admins only';
  end if;
  select status, name into v_old, v_name from public.societies where id = p_id;
  update public.societies set status = p_status, verified = p_verified where id = p_id;
  if p_status = 'approved' and v_old <> 'approved' then
    insert into public.notifications (user_id, kind, title, body, society_id)
    select m.user_id, 'society_approved', 'Your society is live', v_name || ' is now visible to every student.', p_id
    from public.society_members m where m.society_id = p_id;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Moderation: reports can be resolved, and admins can take an event down.
-- ---------------------------------------------------------------------------
alter table public.events add column removed_at timestamptz;
alter table public.reports add column resolved_at timestamptz;
alter table public.reports add column resolution text check (resolution in ('dismissed', 'removed'));

drop policy "read public events" on public.events;
create policy "read public events" on public.events
  for select using (
    (status in ('published', 'cancelled')
      and removed_at is null
      and exists (select 1 from public.societies s where s.id = society_id and s.status = 'approved'))
    or public.is_society_member(society_id)
    or public.is_platform_admin()
  );

create or replace function public.list_open_reports()
returns table (
  id uuid,
  target_type text,
  target_id uuid,
  target_name text,
  reason text,
  report_count bigint,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'Admins only';
  end if;
  return query
    select r.id, r.target_type, r.target_id,
      coalesce(e.title, s.name, b.title, 'Unknown') as target_name,
      r.reason,
      count(*) over (partition by r.target_type, r.target_id) as report_count,
      r.created_at
    from public.reports r
    left join public.events e on r.target_type = 'event' and e.id = r.target_id
    left join public.societies s on r.target_type = 'society' and s.id = r.target_id
    left join public.banners b on r.target_type = 'banner' and b.id = r.target_id
    where r.resolved_at is null
    order by r.created_at;
end;
$$;

-- Resolving one report resolves every open report on the same target.
create or replace function public.resolve_report(p_report_id uuid, p_action text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_report public.reports;
begin
  if not public.is_platform_admin() then
    raise exception 'Admins only';
  end if;
  if p_action not in ('dismissed', 'removed') then
    raise exception 'Unknown action';
  end if;
  select * into v_report from public.reports where id = p_report_id;
  if p_action = 'removed' then
    if v_report.target_type = 'event' then
      update public.events set removed_at = now() where id = v_report.target_id;
    elsif v_report.target_type = 'society' then
      update public.societies set status = 'rejected' where id = v_report.target_id;
    elsif v_report.target_type = 'banner' then
      update public.banners set status = 'rejected' where id = v_report.target_id;
    end if;
  end if;
  update public.reports set resolved_at = now(), resolution = p_action
    where target_type = v_report.target_type and target_id = v_report.target_id and resolved_at is null;
end;
$$;

-- ---------------------------------------------------------------------------
-- Account deletion: hand societies to another committee member first.
-- ---------------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_event uuid;
  v_society uuid;
  v_heir uuid;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  -- Free up seats first so waitlists move and counts stay right.
  for v_event in
    select event_id from public.registrations where user_id = v_uid and status <> 'cancelled'
  loop
    perform public.cancel_registration(v_event);
  end loop;
  -- Promote the longest-serving admin (or editor) of each society this user owns.
  for v_society in
    select society_id from public.society_members where user_id = v_uid and role = 'owner'
  loop
    select user_id into v_heir from public.society_members
      where society_id = v_society and user_id <> v_uid
      order by (role = 'admin') desc, created_at
      limit 1;
    if v_heir is not null then
      update public.society_members set role = 'owner' where society_id = v_society and user_id = v_heir;
    end if;
  end loop;
  delete from auth.users where id = v_uid;
end;
$$;

commit;
